import json,os,subprocess,sys
p,c,*a=sys.argv[1:];f='driver-run.json'
if c=='status':
 s=os.environ.get('OPENWIZ_CLOUDROOM_STATE') or os.path.expanduser('~/.local/state/openwiz-cloudroom')
 t=json.load(open(os.path.join(s,json.load(open(f))['run']+'.json')))['thread']
 r=subprocess.run([p,'thread','show',t],stdin=subprocess.DEVNULL,capture_output=True,text=True)
 o=json.loads(r.stdout) if r.returncode==0 else {}
 print(json.dumps({k:o.get(k) for k in ('projectId','archived')}));sys.exit(r.returncode)
if c=='start':
 if os.path.exists(f):sys.exit(2)
 q=dict(zip(('repository','ticket','skill','harness','model'),a));q['ticket']=int(q['ticket'])
else:q=None if c=='version' else {'run':json.load(open(f))['run']}
r=subprocess.run([p,c],input='' if q is None else json.dumps(q),capture_output=True,text=True)
o=json.loads(r.stdout)
if c=='start' and r.returncode==0:
 with open(f,'x') as w:json.dump({'run':o['run']},w)
 o['saved']=True
print(json.dumps(o));sys.exit(r.returncode)

